  if (!address || typeof address === 'string') throw new Error('Expected a private test port.');
  return {
    url: `http://127.0.0.1:${address.port}/`,
    close: () =>
      new Promise<void>((closed, reject) => {
        server.close((error) => {
          if (error) reject(error);
          else closed();
        });
      }),
  };
}

